<script setup lang="ts">
import { computed, ref } from 'vue'
import { api, pretty, terminal } from '../api'
import type { Evidence, Event, Task } from '../types'
const props = defineProps<{task:Task;events:Event[];evidence:Evidence|null;editable:boolean;inspection:boolean}>()
const emit = defineEmits<{cancel:[]}>()
const prompts=ref<unknown>(null), promptError=ref('')
const warnings=computed(()=>props.events.filter(e=>['model_invalid_response','model_retry','model_timeout','model_failed','tool_denied','tool_failed'].includes(e.type)))
const duration=computed(()=>Math.max(0,(Date.parse(props.task.updated_at)-Date.parse(props.task.created_at))/1000).toFixed(1))
async function loadPrompts(){try{prompts.value=await api(`/tasks/${props.task.id}/prompts`)}catch(e){promptError.value=String(e)}}
</script>
<template><section class="panel task-detail"><div class="section-top"><div><p class="eyebrow">TASK / {{task.id.slice(0,8)}}</p><h2>{{task.goal}}</h2></div><span class="badge" :class="task.status">{{task.status.replaceAll('_',' ')}}</span></div><p class="muted">{{new Date(task.created_at).toLocaleString()}} · {{duration}}s to last update · {{task.options.project}} / {{task.options.workspace}}</p><button v-if="!terminal(task.status) || task.status==='waiting_for_approval'" :disabled="!editable" @click="emit('cancel')">Cancel task</button><p v-if="task.error" class="error">{{task.error}}</p><div class="detail-grid"><div><h3>Agent summary <span class="muted">Unverified claims</span></h3><pre>{{task.result?.summary || 'Awaiting agent result…'}}</pre><h3>Supervisor plan</h3><pre>{{task.result?.plan || 'No supervisor plan recorded.'}}</pre><details><summary>Workers and models used</summary><pre>{{pretty({workers:task.result?.workers,models:task.result?.models,results:task.result?.worker_results})}}</pre></details></div><div><h3>Verified execution evidence</h3><p class="muted">{{evidence?.scope}}</p><h4>Files created / modified</h4><ul v-if="evidence?.files_modified.length"><li v-for="file in evidence.files_modified" :key="file"><code>{{file}}</code></li></ul><p v-else class="muted">No successful file writes recorded.</p><h4>Tests actually executed</h4><pre>{{pretty(evidence?.tests_executed || [])}}</pre><details><summary>Verification actions and tool results</summary><pre>{{pretty(evidence?.tool_calls || [])}}</pre></details><h4>Approvals</h4><pre>{{pretty(task.result?.pending_approvals || events.filter(e=>e.type==='privileged_action_requested').map(e=>e.payload))}}</pre><p class="muted">Privileged approval uses the separate operator CLI. Waiting tasks do not auto-resume.</p></div></div><details v-if="warnings.length" open><summary>Warnings, invalid responses and retries · {{warnings.length}}</summary><pre>{{pretty(warnings.map(e=>({type:e.type,agent:e.actor,...e.payload})))}}</pre></details><div class="section-top"><h3>Live execution</h3><span class="muted">Existing audit stream · polls every 2s</span></div><div class="events"><div v-for="event in events" :key="event.id" class="event"><time>{{new Date(event.timestamp).toLocaleTimeString()}}</time><span>{{event.actor || 'runtime'}}</span><details><summary :class="{'red':event.type.includes('denied')||event.type.includes('failed'),'blue':event.type==='model_request'}">{{event.type.replaceAll('_',' ')}} <code>{{event.payload.tool || event.payload.model || ''}}</code></summary><pre>{{pretty(event.payload)}}</pre></details></div><p v-if="!events.length" class="muted">Waiting for execution events.</p></div><details><summary>Development prompt inspection · {{inspection?'enabled, session only':'disabled'}}</summary><p class="muted">Default audit storage contains prompt metadata and hashes only. Inspection is operator-only and loopback-only; the session cache is bounded and cleared on shutdown.</p><button v-if="inspection && editable" @click="loadPrompts">Inspect session prompts</button><p class="error">{{promptError}}</p><pre v-if="prompts">{{pretty(prompts)}}</pre></details></section></template>
